mapper.update:
UPDATE distributed_lock
SET expired_time = NOW(),
    revision     = revision + 1
WHERE lock_key   = #{key}
  AND lock_value = #{lockValue}

UPDATE distributed_lock
SET expired_time = DATE_ADD(NOW(), INTERVAL #{expireSeconds} SECOND),
    revision     = revision + 1
WHERE lock_key   = #{key}
  AND lock_value = #{lockValue}
  AND expired_time > NOW()
